'use client';
import {useState} from 'react';
import type {SupabaseClient} from '@supabase/supabase-js';
import {MaintenanceTaskClosure} from '@/components/maintenance-task-closure';
import {timelineTone,timelineStatus} from '@/lib/maintenance-wall-state';
import type {WallPost} from '@/components/operational-wall';
const initial={id:'qa',revision:1,category:'Voo de manutenção',title:'Giro de verificação',body:'Resultado satisfatório',priority:'urgent',createdAt:'2026-09-11T10:00:00Z',comments:[],views:[],history:[],technicalCase:{priority:'urgent',report:'report',official:'evaluation',aircraft:'evaluation',investigation:'triage'},actions:[{id:'action',status:'satisfactory',executions:[{at:'2026-09-11T11:00:00Z',result:'satisfactory',description:'OK',employeeNumber:'M'}]}]} as unknown as WallPost;
const client={from:(table:string)=>{const query={select:()=>query,eq:()=>query,single:async()=>({data:table==='maintenance_records'?{id:'record',revision:2,technical_case:initial.technicalCase}:{revision:1,data:{...initial,maintenanceRecordId:'record'}},error:null})};return query;},rpc:async(name:string,args:unknown)=>(await fetch('/__closure_test',{method:'POST',body:JSON.stringify({name,args})})).json()} as unknown as SupabaseClient;
export default function Fixture(){const [post,setPost]=useState(initial),[source,setSource]=useState({...initial,actions:[]}),[signed,setSigned]=useState(false);return <main className="mx-auto max-w-xl space-y-4 p-4"><article data-testid="giro" className={`rounded-xl border-t-4 bg-white p-4 ${timelineTone(post,'M')}`}><h1>Giro de verificação</h1><p>{timelineStatus(post)}</p></article><article data-testid="source" className={`rounded-xl border-t-4 bg-white p-4 ${timelineTone(source,'M')}`}>HSI miscompare · {timelineStatus(source)}</article><MaintenanceTaskClosure client={client} postId="qa" actionId="action" revision={1} requireSignature={async action=>{setSigned(true);await action();return true;}} onSaved={row=>{setPost({...initial,...row.data} as WallPost);if(row.data.sourceClosed)setSource({...source,technicalCase:{...source.technicalCase!,aircraft:'released',investigation:'closed'}});}}/>{signed?<p>Assinatura solicitada</p>:null}</main>;}
